import java.nio.channels.SelectionKey;
import java.nio.channels.SocketChannel;

public class NioBitManipulationDemo {
    // Define custom bit masks for low-level stream state tracking
    public static final int STATE_IDLE      = 1 << 0; // 0001
    public static final int STATE_READING   = 1 << 1; // 0010
    public static final int STATE_WRITING   = 1 << 2; // 0100
    public static final int STATE_ERROR     = 1 << 3; // 1000

    private int currentState = STATE_IDLE;

    public void updateState(int eventBitmask, boolean enable) {
        if (enable) {
            currentState |= eventBitmask; // Set the bit(s)
        } else {
            currentState &= ~eventBitmask; // Clear the bit(s)
        }
    }

    public boolean isReading() {
        // Check if the reading bit is active using bitwise AND
        return (currentState & STATE_READING) != 0;
    }
}
